    mutating func bindMenuChecked(_ item: UInt64, _ signalId: UInt64) {
        let kayaAt = self.begin(UInt16(KAYA_TX_SET_MENU_PROP))
        self.u64(item)
        self.u32(UInt32(KAYA_MPROP_CHECKED))
        self.u32(UInt32(KAYA_SOURCE_SIGNAL))
        self.u64(signalId)
        self.end(kayaAt)
    }

    /// set_menu_prop with a constant value value.
    mutating func setMenuValue(_ item: UInt64, _ value: Double) {
        let kayaAt = self.begin(UInt16(KAYA_TX_SET_MENU_PROP))
        self.u64(item)
        self.u32(UInt32(KAYA_MPROP_VALUE))
        self.u32(UInt32(KAYA_SOURCE_CONST))
        self.value(.f64(value))
        self.end(kayaAt)
    }

    /// set_menu_prop with a signal-bound value value.
    mutating func bindMenuValue(_ item: UInt64, _ signalId: UInt64) {
        let kayaAt = self.begin(UInt16(KAYA_TX_SET_MENU_PROP))
        self.u64(item)
        self.u32(UInt32(KAYA_MPROP_VALUE))
        self.u32(UInt32(KAYA_SOURCE_SIGNAL))
        self.u64(signalId)
        self.end(kayaAt)
    }

    /// set_menu_prop with a constant icon value.
    mutating func setMenuIcon(_ item: UInt64, _ handle: UInt64) {
        let kayaAt = self.begin(UInt16(KAYA_TX_SET_MENU_PROP))
        self.u64(item)
        self.u32(UInt32(KAYA_MPROP_ICON))
        self.u32(UInt32(KAYA_SOURCE_CONST))
        self.value(.blob(handle))
        self.end(kayaAt)
    }

    /// set_menu_prop with a constant primary value.
    mutating func setMenuPrimary(_ item: UInt64, _ primary: Bool) {
        let kayaAt = self.begin(UInt16(KAYA_TX_SET_MENU_PROP))
        self.u64(item)
        self.u32(UInt32(KAYA_MPROP_PRIMARY))
        self.u32(UInt32(KAYA_SOURCE_CONST))
        self.value(.bool(primary))
        self.end(kayaAt)
    }

    /// set_menu_prop with a constant shortcut value, canonicalized here
    /// (the one binding-tier shortcut parser — no call site bypasses it).
    mutating func setMenuShortcut(_ item: UInt64, _ shortcut: String) {
        let kayaAt = self.begin(UInt16(KAYA_TX_SET_MENU_PROP))
        self.u64(item)
        self.u32(UInt32(KAYA_MPROP_SHORTCUT))
        self.u32(UInt32(KAYA_SOURCE_CONST))
        self.value(.str(kayaCanonicalizeShortcut(shortcut)))
        self.end(kayaAt)
    }

    /// set_menu_prop with a constant role value.
    mutating func setMenuRole(_ item: UInt64, _ role: String) {
        let kayaAt = self.begin(UInt16(KAYA_TX_SET_MENU_PROP))
        self.u64(item)
        self.u32(UInt32(KAYA_MPROP_ROLE))
        self.u32(UInt32(KAYA_SOURCE_CONST))
        self.value(.str(role))
        self.end(kayaAt)
    }

    /// set_menu_prop with a constant symbol value.
    mutating func setMenuSymbol(_ item: UInt64, _ symbol: Int64) {
        let kayaAt = self.begin(UInt16(KAYA_TX_SET_MENU_PROP))
        self.u64(item)
        self.u32(UInt32(KAYA_MPROP_SYMBOL))
        self.u32(UInt32(KAYA_SOURCE_CONST))
        self.value(.i64(symbol))
        self.end(kayaAt)
    }

    func submit() {
        bytes.withUnsafeBytes { raw in
            kaya_submit(raw.bindMemory(to: UInt8.self).baseAddress, UInt(raw.count))
        }
    }
}

let kayaShortcutNamedKeys: Set<String> = ["enter", "escape", "delete", "left", "right", "up", "down", "f1", "f2", "f3", "f4", "f5", "f6", "f7", "f8", "f9", "f10", "f11", "f12", "comma", "period", "slash", "backslash", "minus", "equal", "leftbracket", "rightbracket"]

/// The one binding-tier shortcut parser (DESIGN.md, Menus).
/// Canonicalize a shortcut spelling to the wire form: lowercase
/// '+'-joined tokens, modifiers ordered primary, shift, alt, then one
/// key (a-z, 0-9, or the closed named set). Accepts ASCII case
/// variants and any modifier order; traps on whitespace, empty tokens,
/// repeated modifiers, aliases (ctrl/cmd/option), and unknown or
/// multiple or missing keys. POLICY stays at the core: escape,
/// shift-only and bare alphanumerics, and the reserved floor are
/// validated there, on the canonical spelling, never rewritten.
func kayaCanonicalizeShortcut(_ spelling: String) -> String {
    if spelling.isEmpty {
        preconditionFailure("kaya: shortcut is empty")
    }
    for ch in spelling {
        if ch == " " || ch == "\t" || ch == "\n" || ch == "\u{0B}" || ch == "\u{0C}" || ch == "\r" {
            preconditionFailure("kaya: shortcut \"\(spelling)\" contains whitespace")
        }
    }
    let parts = spelling.lowercased()
        .split(separator: "+", omittingEmptySubsequences: false)
        .map(String.init)
    for p in parts where p.isEmpty {
        preconditionFailure("kaya: shortcut \"\(spelling)\" has an empty token")
    }
    let key = parts[parts.count - 1]
    var primary = false, shift = false, alt = false
    for m in parts.dropLast() {
        let repeated: Bool
        switch m {
        case "primary":
            repeated = primary
            primary = true
        case "shift":
            repeated = shift
            shift = true
        case "alt":
            repeated = alt
            alt = true
        default:
            preconditionFailure("kaya: shortcut \"\(spelling)\" has an unknown modifier \"\(m)\" (the portable modifiers are primary, shift, alt; aliases like ctrl, cmd, and option are not accepted)")
        }
        if repeated {
            preconditionFailure("kaya: shortcut \"\(spelling)\" repeats modifier \"\(m)\"")
        }
    }
    let alnum = key.count == 1 && (key.first!.isASCII && (key.first!.isLowercase || key.first!.isNumber))
    if !alnum && !kayaShortcutNamedKeys.contains(key) {
        preconditionFailure("kaya: shortcut \"\(spelling)\" key \"\(key)\" is outside the floor (one of a-z, 0-9, or the closed named set)")
    }
    return (primary ? "primary+" : "") + (shift ? "shift+" : "") + (alt ? "alt+" : "") + key
}

/// One value of a representation. Its own type rather than a case
/// on KayaValue, because bytes reach a guest ONLY here — nothing
/// else on the occurrence channel has ever carried them.
enum KayaClipPart {
    case str(String)
    case i64(Int64)
    case bytes([UInt8])
}

/// One representation as the decoder hands it over: the clip kind,
/// and its parts with blobs already redeemed. The sum itself is the
/// hand-written tier's — this is the taste-free shape the wire
/// carries.
///
/// `kind` is a SINGLE member of the clip enum and never a mask (you
/// offer many and you receive one); 0 with no parts is the universal
/// empty answer.
struct KayaClipValues {
    let kind: UInt32
    let parts: [KayaClipPart]
}

/// Decode a representation at `at`: the clip kind, then its Values
/// block. Blobs are redeemed and RELEASED here.
func kayaParseClip(_ raw: UnsafeRawBufferPointer, _ at: Int)
    -> (clip: KayaClipValues, next: Int)
{
    let kind = raw.loadUnaligned(fromByteOffset: at, as: UInt32.self)
    let count = Int(raw.loadUnaligned(fromByteOffset: at + 8, as: UInt32.self))
    var at = at + 16
    var parts: [KayaClipPart] = []
    for _ in 0..<count {
        let vtype = raw.loadUnaligned(fromByteOffset: at, as: UInt32.self)
        let vlen = Int(raw.loadUnaligned(fromByteOffset: at + 4, as: UInt32.self))
        switch vtype {
        case UInt32(KAYA_VALUE_I64):
            parts.append(.i64(raw.loadUnaligned(fromByteOffset: at + 8, as: Int64.self)))
        case UInt32(KAYA_VALUE_BLOB):
            let handle = raw.loadUnaligned(fromByteOffset: at + 8, as: UInt64.self)
            var length = 0
            // COPY THEN RELEASE, in that order: the pointer borrows
            // core memory that the release frees.
            if let data = kaya_occurrence_blob(handle, &length) {
                parts.append(.bytes([UInt8](UnsafeBufferPointer(start: data, count: length))))
            } else {
                parts.append(.bytes([]))
            }
            kaya_occurrence_blob_release(handle)
        default:
            parts.append(.str(String(
                decoding: raw[(at + 8)..<(at + 8 + vlen)], as: UTF8.self)))
        }
        at += 8 + ((vlen + 7) & ~7)
    }
    return (KayaClipValues(kind: kind, parts: parts), at)
}

/// Decode one occurrence record (header included); nil for pad or
/// unknown kinds. keys is [] when id is a widget id; otherwise id is
/// a template node id and keys is the copy's key path, outermost
/// first. payload is the entry's new text for TEXT_CHANGED, the
/// checkbox's new state for TOGGLED, the slider's new value for
/// VALUE_CHANGED, nil for clicks.
func kayaParseOccurrence(_ rec: [UInt8])
    -> (kind: UInt16, id: UInt64, keys: [KayaValue], payload: KayaValue?, files: [KayaPickedFile], clip: KayaClipValues?)?
{
    rec.withUnsafeBytes { raw in
        let kind = raw.loadUnaligned(fromByteOffset: 4, as: UInt16.self)
        guard kind == UInt16(KAYA_OCCURRENCE_BUTTON_CLICKED)
            || kind == UInt16(KAYA_OCCURRENCE_TEXT_CHANGED)
            || kind == UInt16(KAYA_OCCURRENCE_TOGGLED)
            || kind == UInt16(KAYA_OCCURRENCE_VALUE_CHANGED)
            || kind == UInt16(KAYA_OCCURRENCE_CLOSE_REQUESTED)
            || kind == UInt16(KAYA_OCCURRENCE_WINDOW_CLOSED)
            || kind == UInt16(KAYA_OCCURRENCE_ALERT_RESULT)
            || kind == UInt16(KAYA_OCCURRENCE_ENTRY_POPPED)
            || kind == UInt16(KAYA_OCCURRENCE_BACK_REQUESTED)
            || kind == UInt16(KAYA_OCCURRENCE_SECTION_SELECTED)
            || kind == UInt16(KAYA_OCCURRENCE_MENU_ACTIVATED)
            || kind == UInt16(KAYA_OCCURRENCE_MENU_TOGGLED)
            || kind == UInt16(KAYA_OCCURRENCE_MENU_VALUE_CHANGED)
            || kind == UInt16(KAYA_OCCURRENCE_FILE_DIALOG_RESULT)
            || kind == UInt16(KAYA_OCCURRENCE_CLIPBOARD_RESULT)
            || kind == UInt16(KAYA_OCCURRENCE_PASTED)
            || kind == UInt16(KAYA_OCCURRENCE_UNDONE)
            || kind == UInt16(KAYA_OCCURRENCE_REDONE)
            || kind == UInt16(KAYA_OCCURRENCE_SORT_REQUESTED)
        else { return nil }
        let id = raw.loadUnaligned(fromByteOffset: 8, as: UInt64.self)
        if kind == UInt16(KAYA_OCCURRENCE_ALERT_RESULT) {
            // The alert's one answer: id + u32 choice (ALERT_CHOICE_*).
            let choice = raw.loadUnaligned(fromByteOffset: 16, as: UInt32.self)
            return (kind, id, [], .i64(Int64(choice)), [], nil)
        }
        if kind == UInt16(KAYA_OCCURRENCE_FILE_DIALOG_RESULT) {
            // id, a count, then three Values per file
            // (handle, name, local_path). EMPTY IS CANCEL.
            let count = Int(raw.loadUnaligned(fromByteOffset: 16, as: UInt32.self))
            var at = 32  // past id, count, pad, values count, reserved
            var files: [KayaPickedFile] = []
            for _ in 0..<count {
                var parts: [KayaValue] = []
                for _ in 0..<3 {
                    let vtype = raw.loadUnaligned(fromByteOffset: at, as: UInt32.self)
                    let vlen = Int(raw.loadUnaligned(fromByteOffset: at + 4, as: UInt32.self))
                    if vtype == UInt32(KAYA_VALUE_I64) {
                        parts.append(.i64(raw.loadUnaligned(fromByteOffset: at + 8, as: Int64.self)))
                    } else {
                        let bytes = (0..<vlen).map { raw[at + 8 + $0] }
                        parts.append(.str(String(decoding: bytes, as: UTF8.self)))
                    }
                    at += 8 + (vlen + 7) & ~7
                }
                guard case .i64(let handle) = parts[0],
                      case .str(let name) = parts[1],
                      case .str(let localPath) = parts[2] else { continue }
                files.append(KayaPickedFile(
                    handle: UInt64(handle), name: name, localPath: localPath))
            }
            return (kind, id, [], nil, files, nil)
        }
        if kind == UInt16(KAYA_OCCURRENCE_CLIPBOARD_RESULT) {
            let (clip, _) = kayaParseClip(raw, 16)
            return (kind, id, [], nil, [], clip)
        }
        // Surface lifecycle records carry the surface id alone
        // (derived from the record shapes).
        if kind == UInt16(KAYA_OCCURRENCE_CLOSE_REQUESTED)
            || kind == UInt16(KAYA_OCCURRENCE_WINDOW_CLOSED)
            || kind == UInt16(KAYA_OCCURRENCE_ENTRY_POPPED)
            || kind == UInt16(KAYA_OCCURRENCE_BACK_REQUESTED)
        {
            return (kind, id, [], nil, [], nil)
        }
        // Surface-pair records (window, section): the SECOND id
        // keys the handler; the first rides as the payload.
        if kind == UInt16(KAYA_OCCURRENCE_SECTION_SELECTED)
        {
            let section = raw.loadUnaligned(fromByteOffset: 16, as: UInt64.self)
            return (kind, section, [], .i64(Int64(bitPattern: id)), [], nil)
        }
        let pathLen = raw.loadUnaligned(fromByteOffset: 16, as: UInt32.self)
        var keys: [KayaValue] = []
        var at = 24
        for _ in 0..<pathLen {
            let vtype = raw.loadUnaligned(fromByteOffset: at, as: UInt32.self)
            let vlen = Int(raw.loadUnaligned(fromByteOffset: at + 4, as: UInt32.self))
            switch vtype {
            case UInt32(KAYA_VALUE_BOOL):
                keys.append(.bool(raw[at + 8] != 0))
            case UInt32(KAYA_VALUE_I64):
                keys.append(.i64(Int64(bitPattern:
                    raw.loadUnaligned(fromByteOffset: at + 8, as: UInt64.self))))
            case UInt32(KAYA_VALUE_F64):
                keys.append(.f64(Double(bitPattern:
                    raw.loadUnaligned(fromByteOffset: at + 8, as: UInt64.self))))
            default:
                keys.append(.str(String(
                    decoding: raw[(at + 8)..<(at + 8 + vlen)], as: UTF8.self)))
            }
            at += 8 + ((vlen + 7) & ~7)
        }
        var payload: KayaValue? = nil
        if kind == UInt16(KAYA_OCCURRENCE_TEXT_CHANGED)
            || kind == UInt16(KAYA_OCCURRENCE_TOGGLED)
            || kind == UInt16(KAYA_OCCURRENCE_VALUE_CHANGED)
            || kind == UInt16(KAYA_OCCURRENCE_MENU_TOGGLED)
            || kind == UInt16(KAYA_OCCURRENCE_MENU_VALUE_CHANGED)
        {
            let ptype = raw.loadUnaligned(fromByteOffset: at, as: UInt32.self)
            let plen = Int(raw.loadUnaligned(fromByteOffset: at + 4, as: UInt32.self))
            switch ptype {
            case UInt32(KAYA_VALUE_BOOL):
                payload = .bool(raw[at + 8] != 0)
            case UInt32(KAYA_VALUE_I64):
                payload = .i64(Int64(bitPattern:
                    raw.loadUnaligned(fromByteOffset: at + 8, as: UInt64.self)))
            case UInt32(KAYA_VALUE_F64):
                payload = .f64(Double(bitPattern:
                    raw.loadUnaligned(fromByteOffset: at + 8, as: UInt64.self)))
            default:
                payload = .str(String(decoding: raw[(at + 8)..<(at + 8 + plen)], as: UTF8.self))
            }
        }
        var clip: KayaClipValues? = nil
        if kind == UInt16(KAYA_OCCURRENCE_PASTED)
        {
            clip = kayaParseClip(raw, at).clip
        }
        return (kind, id, keys, payload, [], clip)
    }
}
